import { createExternalMessage, createMessage } from '@vocably/hermes';
const createScope = (scope) => (identifier) => createMessage(`${scope}.${identifier}`);
const createScopedMessage = createScope('vocably');
export const [isLoggedIn, onIsLoggedInRequest] = createScopedMessage('isLoggedIn');
export const [getSettings, onGetSettingsRequest] = createScopedMessage('getSettings');
export const [setSettings, onSetSettingsRequest] = createScopedMessage('setSettings');
export const [isActive, onIsActiveRequest] = createScopedMessage('isActive');
export const [isEligibleForTrial, onIsEligibleForTrialRequest] = createScopedMessage('isEligibleForTrial');
export const [getCardsLimit, onGetCardsLimitRequest] = createScopedMessage('getCardsLimit');
export const [getUserEmail, onGetUserEmail] = createScopedMessage('getUserEmail');
export const [analyze, onAnalyzeRequest] = createScopedMessage('analyze');
export const [explain, onExplainRequest] = createScopedMessage('explain');
export const [removeCard, onRemoveCardRequest] = createScopedMessage('removeCard');
export const [addCard, onAddCardRequest] = createScopedMessage('addCard');
export const [listLanguages, onListLanguagesRequest] = createScopedMessage('listLanguages');
export const [listTargetLanguages, onListTargetLanguagesRequest] = createScopedMessage('listTargetLanguages');
export const [getLocationLanguage, onGetLocationLanguageRequest] = createScopedMessage('getLocationLanguage');
export const [saveLocationLanguage, onSaveLocationLanguageRequest] = createScopedMessage('saveLocationLanguage');
export const [getLanguagePairs, onGetLanguagePairs] = createScopedMessage('getLanguagePairs');
export const [ping, onPing] = createScopedMessage('ping');
export const [getInternalProxyLanguage, onGetInternalProxyLanuage] = createScopedMessage('getInternalProxyLanguage');
export const [setInternalProxyLanguage, onSetInternalProxyLanguage] = createScopedMessage('setInternalProxyLanguage');
export const [getInternalSourceLanguage, onGetInternalSourceLanguage] = createScopedMessage('getInternalSourceLanguage');
export const [setInternalSourceLanguage, onSetInternalSourceLanguage] = createScopedMessage('setInternalSourceLanguage');
export const [isUserKnowsHowToAdd, onIsUserKnowsHowToAdd] = createScopedMessage('isUserKnowsHowToAdd');
export const [setUserKnowsHowToAdd, onSetUserKnowsHowToAdd] = createScopedMessage('setUserKnowsHowToAdd');
export const [pingExternal, onPingExternal] = createExternalMessage('vocably.ping-external');
export const [setProxyLanguage, onSetProxyLanguage] = createExternalMessage('vocably.setProxyLanguage');
export const [getProxyLanguage, onGetProxyLanguage] = createExternalMessage('vocably.getProxyLanguage');
export const [setSourceLanguage, onSetSourceLanguage] = createExternalMessage('vocably.setSourceLanguage');
export const [getSourceLanguage, onGetSourceLanguage] = createExternalMessage('vocably.getSourceLanguage');
export const [getAudioPronunciation, onGetAudioPronunciation] = createScopedMessage('getAudioPronunciation');
export const [askForRating, onAskForRating] = createScopedMessage('askForRating');
export const [saveAskForRatingResponse, onSaveAskForRatingResponse] = createScopedMessage('askForRatingResponse');
export const [playAudioPronunciation, onPlayAudioPronunciation] = createScopedMessage('playAudioPronunciation');
export const [playAudioPronunciationOffscreen, onPlayAudioPronunciationOffscreen,] = createScopedMessage('playAudioPronunciationOffscreen');
export const [canPlayOffScreen, onCanPlayOffScreen] = createScopedMessage('canPlayOffScreen');
export const [updateCard, onUpdateCard] = createScopedMessage('updateCard');
export const [attachTag, onAttachTag] = createScopedMessage('attachTag');
export const [detachTag, onDetachTag] = createScopedMessage('detachTag');
export const [updateTag, onUpdateTag] = createScopedMessage('updateTag');
export const [deleteTag, onDeleteTag] = createScopedMessage('deleteTag');
export const [analyzeUnitsOfSpeech, onAnalyzeUnitsOfSpeech] = createScopedMessage('analyzeUnitsOfSpeech');
